import { useState } from "react";
import styles from "./Thickshakes.module.css";

const SHAKE_DATA = [
  {
    id: 1,
    title: "Chocolate Hazelnut",
    description: "Dark cocoa, toasted hazelnut, and dense velvet texture.",
    price: 289,
    image: "data:image/jpeg;base64,",
  },
  {
    id: 2,
    title: "Salted Caramel",
    description: "Buttery caramel depth balanced with a clean sea-salt finish.",
    price: 279,
    image: "data:image/jpeg;base64,",
  },
  {
    id: 3,
    title: "Peanut Butter Fudge",
    description: "Roasted peanut blend layered with warm fudge ribbons.",
    price: 299,
    image: "data:image/jpeg;base64,",
  },
];

interface ShakeCardProps {
  title: string;
  description: string;
  price: number;
  image: string;
}

function ShakeCard({ title, description, price, image }: ShakeCardProps) {
  const [qty, setQty] = useState(1);

  const changeQty = (delta: number) => {
    setQty((prev) => Math.max(1, prev + delta));
  };

  return (
    <div className={styles.card}>
      <img className={styles.cardImage} src={image} alt={title} />
      <div className={styles.cardBody}>
        <div className={styles.cardTitle}>{title}</div>
        <div className={styles.cardDesc}>{description}</div>
      </div>
      <div className={styles.cardFooter}>
        <div className={styles.price}>&#8377;{price}</div>
        <div className={styles.qtyControl}>
          <button className={styles.qtyBtn} onClick={() => changeQty(-1)}>&#8722;</button>
          <span className={styles.qtyNum}>{qty}</span>
          <button className={styles.qtyBtn} onClick={() => changeQty(1)}>+</button>
        </div>
      </div>
      <button className={styles.addToCart}>
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={1.8} strokeLinecap="round" strokeLinejoin="round">
          <path d="M6 2L3 6v14a2 2 0 002 2h14a2 2 0 002-2V6l-3-4z" />
          <line x1="3" y1="6" x2="21" y2="6" />
          <path d="M16 10a4 4 0 01-8 0" />
        </svg>
        ADD TO CART
      </button>
    </div>
  );
}

export default function Thickshakes() {
  return (
    <div className={styles.wrapper}>
      <section className={styles.section}>
        <div className={styles.sectionHeader}>
          <div className={styles.titleBlock}>
            <h2>Thick Shakes</h2>
            <p>Dessert-first blends with luxurious body. Built to be spoonable treats.</p>
          </div>
          <a href="#" className={styles.seeAllBtn}>
            See All
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2.2} strokeLinecap="round" strokeLinejoin="round">
              <path d="M5 12h14M13 6l6 6-6 6" />
            </svg>
          </a>
        </div>

        <div className={styles.divider} />

        <div className={styles.cardsGrid}>
          {SHAKE_DATA.map((shake) => (
            <ShakeCard key={shake.id} {...shake} />
          ))}
        </div>
      </section>
    </div>
  );
}
